@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Marcellus&display=swap');
:root{--ink:#17232a;--muted:#75838a;--paper:#f5f3ed;--line:#e4e6df;--sea:#4b9b9f;--gold:#d5a85e;--deep:#14252d}*{box-sizing:border-box}body{margin:0;background:#e8e8e1;color:var(--ink);font-family:'DM Sans',sans-serif;min-height:100vh}.game-shell{max-width:1450px;margin:auto;padding:0 36px}.topbar{height:74px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d6dad4}.brand{display:flex;gap:12px;align-items:center;color:var(--ink);text-decoration:none;font-size:12px;letter-spacing:.16em;font-weight:600}.brand b{font-weight:700}.brand-mark{font-size:23px;color:#bf9250}.world-meta{font-size:10px;font-weight:700;letter-spacing:.15em;color:#526269;display:flex;gap:12px;align-items:center}.world-meta i{font-style:normal;color:#b29b74}.live-dot,.save-dot{height:7px;width:7px;background:#67a9a0;border-radius:100%;display:inline-block;box-shadow:0 0 0 3px #dceae4}.icon-button{border:1px solid #d8dcd5;border-radius:3px;background:transparent;color:#4d5b5e;padding:9px 13px;font:600 10px 'DM Sans';letter-spacing:.09em}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 302px;gap:20px;padding:24px 0 15px}.scene-frame{height:min(64vh,560px);min-height:390px;background:#a9c5c3;position:relative;overflow:hidden;border-radius:4px;box-shadow:0 14px 34px #26393c20}.scene-frame canvas{width:100%;height:100%;display:block}.scene-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#07151c65 0%,transparent 23%,transparent 72%,#07151c39 100%),linear-gradient(90deg,#09191c12,transparent 30%,transparent 80%,#09191c17)}.scene-topline{position:absolute;top:20px;left:22px;right:22px;display:flex;justify-content:space-between;align-items:center;color:#fff;text-shadow:0 1px 5px #172a2c}.location-tag,.weather-tag{font-size:9px;letter-spacing:.15em;font-weight:600}.location-tag span{color:#e5c27e;font-size:15px;vertical-align:-1px;margin-right:5px}.weather-tag{opacity:.9}.scene-hint{position:absolute;bottom:16px;left:50%;transform:translateX(-50%);white-space:nowrap;border:1px solid #ffffff50;background:#10292e62;color:#fff;padding:9px 15px;border-radius:2px;font-size:9px;letter-spacing:.12em;backdrop-filter:blur(5px)}.scene-hint span{color:#e7c887;font-weight:700}.scene-hint i{font-style:normal;margin:0 9px;color:#ffffff70}.action-dock{height:84px;background:#fff;border:1px solid #e4e5df;display:flex;align-items:center;padding:0 19px;gap:24px}.character-chip{display:flex;gap:12px;align-items:center;min-width:195px}.portrait{width:43px;height:43px;background:#e4f0ed;border-radius:50%;display:grid;place-items:center;color:#518c8e;font-size:21px;border:1px solid #d3e2dd}.character-chip strong{display:block;font:16px Marcellus,serif;margin-top:3px}.eyebrow{font-size:8px;letter-spacing:.14em;color:#819095}.vitals{flex:1;display:grid;gap:10px;max-width:390px}.vital-row{display:grid;grid-template-columns:52px 1fr 54px;gap:8px;align-items:center;font-size:8px;letter-spacing:.1em;color:#738087}.vital-row b{font-size:8px;text-align:right;font-weight:600;letter-spacing:0}.meter{height:4px;background:#e9e9e2;border-radius:6px;overflow:hidden}.meter i{height:100%;display:block;background:#d58271;border-radius:6px;transition:width .25s}.meter.focus i{background:#70aeb0}.dock-actions{display:flex;gap:7px;margin-left:auto}.action-key{border:1px solid #e4e6e2;background:#fff;padding:7px 10px;display:grid;grid-template-columns:22px auto;align-items:center;gap:5px;color:#68767b;font:600 8px 'DM Sans';letter-spacing:.09em}.action-key kbd{font:10px 'DM Sans';color:#b48e54}.side-panel{height:calc(min(64vh,560px) + 84px);min-height:474px;background:var(--paper);border:1px solid #e2e4dc;border-radius:4px;display:flex;flex-direction:column}.panel-tabs{display:flex;border-bottom:1px solid var(--line);height:52px;flex-shrink:0}.tab{background:none;border:0;border-bottom:2px solid transparent;flex:1;font:600 9px 'DM Sans';letter-spacing:.13em;color:#8a9595}.tab.active{color:#3f7f80;border-bottom-color:#68a4a0}.panel-content{padding:21px 20px;overflow:auto;flex:1}.side-footer{border-top:1px solid var(--line);height:38px;display:flex;align-items:center;padding:0 17px;gap:9px;font-size:8px;letter-spacing:.1em;color:#87918f;flex-shrink:0}.save-dot{width:6px;height:6px;box-shadow:none}.bottomline{height:35px;display:flex;justify-content:space-between;align-items:center;color:#849091;font-size:8px;letter-spacing:.12em}.bottomline i{font-style:normal;color:#c3a871;margin:0 7px}.panel-kicker{font-size:8px;color:#b08b51;letter-spacing:.17em;font-weight:700}.panel-heading{font:22px Marcellus,serif;margin:8px 0 7px;color:#27383c}.panel-copy{font-size:11px;line-height:1.65;color:#778487;margin:0}.quest-card{margin-top:19px;padding:14px;background:#fff;border:1px solid #e9e9e2;border-left:2px solid #6fa6a1}.quest-title{font:15px Marcellus,serif;margin:5px 0 7px}.quest-card p{font-size:10px;line-height:1.55;color:#788489;margin:0}.quest-progress{margin-top:13px;font-size:8px;letter-spacing:.11em;color:#74817e;display:flex;justify-content:space-between}.quest-progress b{color:#598c88}.section-label{font-size:8px;letter-spacing:.16em;color:#899596;font-weight:700;margin:21px 0 10px}.objective{display:flex;gap:9px;align-items:flex-start;font-size:10px;color:#67767a;line-height:1.5;margin:10px 0}.objective i{width:13px;height:13px;flex:none;border:1px solid #bec9c3;border-radius:50%;font-style:normal;color:#fff;text-align:center;font-size:9px}.objective.done i{background:#65a39a;border-color:#65a39a}.objective.done{color:#9aa3a0;text-decoration:line-through}.tip-card{background:#e8efeb;padding:12px 13px;margin-top:18px;font-size:9px;color:#617777;line-height:1.6}.tip-card b{color:#447674}.stat-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:17px}.stat{background:#fff;border:1px solid #e7e8e1;padding:11px}.stat span{font-size:8px;letter-spacing:.1em;color:#8d9996;display:block}.stat b{font:18px Marcellus,serif;display:block;margin-top:5px}.nation-badge{display:inline-flex;padding:6px 9px;background:#e9f1ed;color:#508380;font-size:8px;letter-spacing:.12em;font-weight:700;margin-top:10px}.skill-row{display:flex;align-items:center;gap:10px;padding:11px 0;border-bottom:1px solid #e6e7e0}.skill-icon{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:#e8f0ed;color:#4e8d8a;font-size:14px;flex:none}.skill-row strong{font:13px Marcellus,serif;display:block}.skill-row small{display:block;color:#86918e;font-size:9px;margin-top:3px}.skill-row em{font-size:8px;color:#b68d4f;font-style:normal;margin-left:auto}.overlay{position:fixed;inset:0;background:#101d21a6;backdrop-filter:blur(5px);display:none;align-items:center;justify-content:center;z-index:10;padding:18px}.overlay.open{display:flex}.modal{width:min(570px,100%);background:#f7f5ef;padding:39px 44px;border:1px solid #ffffff65;box-shadow:0 24px 90px #06141670;position:relative;max-height:92vh;overflow:auto}.modal:before{content:'';position:absolute;top:0;left:0;right:0;height:3px;background:linear-gradient(90deg,#77aaa2,#dfc079,#ba7666)}.modal-kicker{font-size:9px;letter-spacing:.2em;color:#9b845b;font-weight:700}.modal h1,.modal h2{font:34px Marcellus,serif;margin:11px 0 12px;color:#23393d}.modal p{font-size:12px;color:#758184;line-height:1.75}.element-seals{display:flex;justify-content:center;gap:18px;margin:26px 0}.seal{width:43px;height:43px;border:1px solid #d9e2dc;border-radius:50%;display:grid;place-items:center;color:#5a9a99;background:#edf2ed;font-size:18px}.seal:nth-child(2){color:#9a8b68}.seal:nth-child(3){color:#bd725f}.seal:nth-child(4){color:#749ea0}.primary-button,.secondary-button{border:0;background:#426e6c;color:white;padding:13px 22px;font:600 9px 'DM Sans';letter-spacing:.16em;cursor:pointer;transition:background .2s,transform .2s}.primary-button:hover{background:#315c5a;transform:translateY(-1px)}.secondary-button{background:transparent;color:#597876;border:1px solid #cbd6d0}.modal-actions{display:flex;justify-content:center;gap:9px;margin-top:24px}.birth-card{margin:20px 0 15px;padding:17px 18px;background:#fff;border:1px solid #e7e8e1}.birth-card .birth-line{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #eff0ea;font-size:11px;color:#718083}.birth-card .birth-line:last-child{border:0}.birth-line b{color:#32494b;font-weight:600}.birth-note{font-size:10px!important;font-style:italic}.dialogue{display:flex;gap:14px;align-items:flex-start;margin:22px 0}.speaker-icon{width:43px;height:43px;background:#e4eeea;border-radius:50%;display:grid;place-items:center;color:#528e89;font-size:19px;flex:none}.dialogue p{margin:0;color:#586b6c}.dialogue b{display:block;font:16px Marcellus,serif;margin-bottom:5px;color:#2e4548}.choice-list{display:grid;gap:8px;margin-top:19px}.choice-button{text-align:left;padding:12px 14px;background:#fff;border:1px solid #e5e6df;color:#435b5b;font:11px 'DM Sans';cursor:pointer}.choice-button:hover{border-color:#72a49d;background:#f4f8f4}.toast{position:absolute;left:50%;top:72px;transform:translate(-50%,-8px);padding:10px 17px;background:#152b2dcf;color:white;font-size:10px;letter-spacing:.06em;opacity:0;transition:.3s;pointer-events:none;white-space:nowrap;z-index:2}.toast.show{opacity:1;transform:translate(-50%,0)}.mobile-pad,.mobile-actions,.mobile-tabs{display:none}
@media(max-width:900px){.game-shell{padding:0 18px}.game-layout{grid-template-columns:minmax(0,1fr) 270px;gap:13px}.scene-frame{min-height:360px}.side-panel{min-height:444px}.action-dock{padding:0 12px;gap:12px}.character-chip{min-width:150px}.dock-actions .action-key{padding:7px}.world-meta{font-size:8px}}
@media(max-width:680px){.game-shell{padding:0 10px}.topbar{height:58px}.brand{font-size:10px;gap:7px}.brand-mark{font-size:19px}.world-meta{font-size:7px;gap:6px;letter-spacing:.08em}.icon-button{padding:7px;font-size:9px}.icon-button span{display:none}.game-layout{display:block;padding:10px 0}.scene-frame{height:56vh;min-height:320px;max-height:520px;border-radius:3px}.scene-topline{top:13px;left:13px;right:13px}.location-tag,.weather-tag{font-size:8px}.weather-tag{max-width:100px;text-align:right}.scene-hint{bottom:12px;font-size:8px;padding:8px 10px}.action-dock{height:76px;padding:0 10px;gap:8px}.character-chip{min-width:0;flex:1;gap:8px}.portrait{width:36px;height:36px}.character-chip strong{font-size:14px}.eyebrow{font-size:7px}.vitals{flex:1.2;gap:9px}.vital-row{grid-template-columns:35px 1fr 42px;gap:5px;font-size:7px}.vital-row b{font-size:7px}.dock-actions{display:none}.side-panel{display:none}.bottomline{font-size:7px}.bottomline span:last-child{display:none}.mobile-tabs{height:43px;background:#fff;border:1px solid #e3e5de;display:flex;justify-content:space-around;align-items:center}.mobile-tabs button{border:0;background:none;color:#71807f;font:600 8px 'DM Sans';letter-spacing:.12em;padding:12px}.mobile-pad{position:absolute;display:grid;grid-template-columns:38px 38px 38px;grid-template-rows:38px 38px;left:13px;bottom:51px;gap:3px}.mobile-pad button,.mobile-actions button{background:#172d32a8;border:1px solid #ffffff56;color:white;border-radius:4px;font-size:12px;touch-action:none}.mobile-pad button:nth-child(1){grid-column:2}.mobile-pad button:nth-child(2){grid-column:1;grid-row:2}.mobile-pad button:nth-child(3){grid-column:2;grid-row:2}.mobile-pad button:nth-child(4){grid-column:3;grid-row:2}.mobile-actions{display:flex;position:absolute;right:13px;bottom:56px;gap:6px}.mobile-actions button{padding:12px 10px;font:600 8px 'DM Sans';letter-spacing:.1em}.modal{padding:32px 23px}.modal h1,.modal h2{font-size:29px}.element-seals{margin:19px 0}.toast{top:55px;max-width:90%;font-size:9px;text-align:center}.bottomline{height:27px}.mobile-tabs{margin-top:0}}

(() => {
  'use strict';
  const canvas = document.querySelector('#world');
  const ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const overlay = $('#overlay');
  const W = 1800, H = 1120;
  const palette = {Water:['#8fc7c8','#548d9b','#d5e6db'],Earth:['#b8aa76','#7b8b59','#d6bd82'],Fire:['#bd8265','#8c5749','#ddaa6d'],Air:['#c7c8b3','#7c9a91','#e2dbbc'],Spirit:['#567981','#387e80','#93d7c2']};
  const locations = [
    {id:'south',name:'Southern Water Tribe',short:'Southern Water Tribe',land:'FROSTFALL VILLAGE',nation:'Water Tribe',element:'Water',weather:'❄  LIGHT SNOW',desc:'An icebound village at the edge of a vast, blue horizon.',npcs:[['Elder Nukka','elder',820,570,'An old waterbender with kind, searching eyes.'],['Miki','local',1080,730,'A curious young fisher, forever collecting stories.'],['Taro','teacher',1320,480,'A patient waterbending teacher.']]},
    {id:'earth',name:'Earth Kingdom',short:'Earth Kingdom',land:'JADE HARBOR',nation:'Earth Kingdom',element:'Earth',weather:'☀  CLEAR SKIES',desc:'A lively harbor opens onto the endless green of the Earth Kingdom.',npcs:[['Captain Ren','elder',790,565,'A retired guard who has seen every road.'],['Lin','local',1080,740,'A quick-witted courier with a map to spare.'],['Master Huan','teacher',1320,475,'A grounded earthbender and an excellent teacher.']]},
    {id:'fire',name:'Fire Nation',short:'Fire Nation',land:'EMBER ISLAND',nation:'Fire Nation',element:'Fire',weather:'☼  WARM BREEZE',desc:'Black-sand shores shimmer beneath the distant volcanoes.',npcs:[['Auntie Suki','elder',790,565,'A warm-hearted innkeeper with a bold past.'],['Pao','local',1090,740,'A young sailor who knows the island paths.'],['Shen','teacher',1320,475,'A focused firebender teaching breath before flame.']]},
    {id:'air',name:'Air Nomads',short:'Air Nomads',land:'WESTERN AIR TEMPLE',nation:'Air Nomads',element:'Air',weather:'☁  HIGH CLOUDS',desc:'Ancient temple bells drift over a sea of clouds.',npcs:[['Sister Amala','elder',790,565,'A gentle keeper of the temple library.'],['Tenzin','local',1090,740,'A playful acolyte with a racing air scooter.'],['Guru Pema','teacher',1320,475,'A quiet airbending master, at home in the sky.']]},
    {id:'swamp',name:'Misty Palms Swamp',short:'Misty Palms Swamp',land:'MISTY PALMS',nation:'Earth Kingdom',element:'Earth',weather:'☁  WARM MIST',desc:'Twisting roots remember every footstep in the deep green.',npcs:[['Old Kori','elder',790,565,'A swamp guide who listens to the trees.'],['Hei Bai','spirit',1190,720,'A masked forest spirit watches from the shadows.']]},
    {id:'ba-sing-se',name:'Ba Sing Se',short:'Ba Sing Se',land:'THE GREAT WALL',nation:'Earth Kingdom',element:'Earth',weather:'☀  CITY BREEZE',desc:'The great inner wall shelters gardens, markets, and a thousand untold lives.',npcs:[['Jin','elder',790,565,'A tea-shop host who has a story for every visitor.'],['Mei','local',1100,740,'A bright-eyed messenger from the upper ring.']]},
    {id:'north',name:'Northern Water Tribe',short:'Northern Water Tribe',land:'MOONLIT HARBOR',nation:'Water Tribe',element:'Water',weather:'❄  POLAR GLOW',desc:'A luminous city of ice rises beneath the northern lights.',npcs:[['Master Yue','teacher',890,530,'A healer who studies the moonlit tides.'],['Nima','local',1200,750,'A cheerful apprentice healer.']]},
    {id:'spirit',name:'Spirit World',short:'Spirit World',land:'THE VEILED GROVE',nation:'Spirit World',element:'Spirit',weather:'✧  SPIRIT LIGHT',desc:'A dreamlike forest where roots glow and the sky remembers.',npcs:[['Hei Bai','spirit',900,580,'The forest spirit is still, listening for a promise.'],['Moon Spirit','spirit',1250,720,'A pale koi circles in a pool of impossible light.']]}
  ];
  const state = {started:false,profile:null,region:'south',spirit:false,x:430,y:610,face:1,walk:0,health:100,focus:60,xp:0,level:1,age:16,day:1,time:8,quest:0,flags:{},mastery:{},technique:0,avatarControl:0,visited:['south'],kills:0,tab:'journal',toastTimer:0,particles:[],hitFlash:0,meditating:false,sound:false};
  const namePool=['Ari','Kavi','Nima','Sora','Ren','Mira','Tavi','Koa','Yuna','Rin','Kai','Lian'];
  const familyPool=['a fisher’s family','a family of healers','a humble village family','a merchant household','a family of storytellers','a respected artisan family','a family of wandering performers'];
  const traits=['Curious','Steadfast','Playful','Patient','Daring','Thoughtful','Kindhearted','Resourceful'];
  const elements=['Water','Earth','Fire','Air'];
  const avatarOdds=0.018;
  let lastFrame=performance.now(), lastSave=0;
  const current=()=>locations.find(v=>v.id===state.region)||locations[0];
  const esc=(s)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');state.toastTimer=2.5;}
  function save(){try{localStorage.setItem('four-elements-save',JSON.stringify(state));}catch(_){}}
  function load(){try{const data=JSON.parse(localStorage.getItem('four-elements-save')||'null');if(data&&data.started&&data.profile){Object.assign(state,data);return true;}}catch(_){}return false;}
  function randomProfile(){const nation=locations.slice(0,4)[Math.floor(Math.random()*4)];const avatar=Math.random()<avatarOdds;const bender=avatar||Math.random()<.69;const element=avatar?null:(bender?nation.element:null);return {name:namePool[Math.floor(Math.random()*namePool.length)],nation:nation.nation,origin:nation.id,background:familyPool[Math.floor(Math.random()*familyPool.length)],bender,element,avatar,trait:traits[Math.floor(Math.random()*traits.length)],born:avatar?'The Avatar':bender?`${element}bender`:'Non-bender'};}
  function showWelcome(){overlay.innerHTML=`<div class="modal welcome"><div class="modal-kicker">A LIVING WORLD · YOUR STORY BEGINS</div><h1>Find your own<br>way in the world.</h1><p>Four nations. A thousand paths. Begin a new life shaped by chance, courage, and the choices only you can make.</p><div class="element-seals"><span class="seal">≈</span><span class="seal">◆</span><span class="seal">♨</span><span class="seal">◌</span></div><p style="text-align:center;font-size:10px">A quiet, original adventure inspired by elemental fantasy.</p><div class="modal-actions"><button class="primary-button" id="beginButton">BEGIN A NEW LIFE</button></div><p id="continueLine" style="text-align:center;margin:15px 0 0"></p></div>`;overlay.classList.add('open');const continueLine=$('#continueLine');if(load()){continueLine.innerHTML='<button class="secondary-button" id="continueButton">CONTINUE JOURNEY</button>';$('#continueButton').onclick=()=>{overlay.classList.remove('open');renderAll();toast('Welcome back, '+state.profile.name+'.');};}$('#beginButton').onclick=()=>{const p=randomProfile();showBirth(p);};}
  function showBirth(p){const home=locations.find(l=>l.id===p.origin);overlay.innerHTML=`<div class="modal"><div class="modal-kicker">A NEW LIFE · ${p.avatar?'A RARE TURN OF FATE':'THE THREADS OF FATE'}</div><h2>${p.avatar?'The cycle begins anew.':'Born beneath a wide sky.'}</h2><p>On a morning much like any other, a new life arrives. The world does not decide who you will become.</p><div class="birth-card"><div class="birth-line"><span>Name</span><b>${esc(p.name)}</b></div><div class="birth-line"><span>Homeland</span><b>${esc(p.nation)}</b></div><div class="birth-line"><span>Family</span><b>${esc(p.background)}</b></div><div class="birth-line"><span>Nature</span><b>${p.avatar?'The Avatar':p.bender?esc(p.element+'bender'):'Non-bender'}</b></div><div class="birth-line"><span>First impression</span><b>${esc(p.trait)}</b></div></div><p class="birth-note">${p.avatar?'The Avatar is a rare soul, born with the potential to learn all four elements.':'Your birth is only a beginning. Teachers, practice, and the choices you make will shape your path.'}</p><div class="modal-actions"><button class="secondary-button" id="rerollButton">ROLL A DIFFERENT FATE</button><button class="primary-button" id="acceptBirth">MEET THE WORLD</button></div></div>`;$('#rerollButton').onclick=()=>showBirth(randomProfile());$('#acceptBirth').onclick=()=>{Object.assign(state,{started:true,profile:p,region:p.origin,x:430,y:610,health:100,focus:60,xp:0,level:1,age:16,quest:0,flags:{},mastery:p.avatar?{}:{[p.element]:0},avatarControl:0,visited:[p.origin],kills:0,spirit:false});if(p.avatar)state.mastery={};if(!p.avatar&&p.bender)state.mastery[p.element]=0;overlay.classList.remove('open');renderAll();toast('A new journey begins in '+home.name+'.');save();};}
  function resize(){const r=canvas.getBoundingClientRect();const d=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.floor(r.width*d);canvas.height=Math.floor(r.height*d);ctx.setTransform(d,0,0,d,0,0);}
  window.addEventListener('resize',resize);
  function draw(){const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;const w=rect.width,h=rect.height,sx=w/W,sy=h/H;ctx.save();ctx.scale(sx,sy);const loc=state.spirit?locations.find(l=>l.id==='spirit'):current();drawLandscape(loc);drawObjects(loc);drawNPCs(loc);drawPlayer();drawEffects();ctx.restore();}
  function rand(seed){let x=Math.sin(seed*127.1+311.7)*43758.5453;return x-Math.floor(x);}
  function drawLandscape(loc){const c=state.spirit?palette.Spirit:palette[loc.element]||palette.Earth;const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,state.spirit?'#344d62':loc.element==='Water'?'#789da8':loc.element==='Fire'?'#dfae7f':'#a9c5bc');sky.addColorStop(.58,state.spirit?'#597d7e':loc.element==='Water'?'#b9cfca':loc.element==='Fire'?'#e7c393':'#e2ddbd');sky.addColorStop(1,state.spirit?'#385b4d':c[1]);ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
    if(loc.element==='Water'&&!state.spirit){ctx.fillStyle='#809eaa';ctx.fillRect(0,715,W,405);for(let y=730;y<1120;y+=36){ctx.strokeStyle=`rgba(231,244,234,${.16+(y%3)*.035})`;ctx.lineWidth=2;ctx.beginPath();for(let x=0;x<=W;x+=40){const yy=y+Math.sin(x*.012+y*.025+state.time)*5;if(x===0)ctx.moveTo(x,yy);else ctx.lineTo(x,yy);}ctx.stroke();}drawIceShelf();}
    else{ctx.fillStyle=state.spirit?'#385c55':c[1];ctx.beginPath();ctx.moveTo(0,670);for(let x=0;x<=W;x+=35)ctx.lineTo(x,640+Math.sin(x*.004+1)*42+Math.sin(x*.013)*15);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();ctx.fillStyle=state.spirit?'#537766':c[0];ctx.beginPath();ctx.moveTo(0,800);for(let x=0;x<=W;x+=32)ctx.lineTo(x,760+Math.sin(x*.006+3)*35);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();if(loc.id==='air'){drawTemple();}else if(loc.id==='fire'){drawVolcano();}else if(loc.id==='earth'||loc.id==='ba-sing-se'){drawCity(loc.id==='ba-sing-se');}else if(loc.id==='swamp'||state.spirit){drawTrees();}else drawHuts(c[2]);}
    // soft floating atmosphere
    for(let i=0;i<20;i++){const x=(rand(i+9)*W+state.time*(loc.element==='Air'?12:3))%W;const y=rand(i+39)*H*.8;ctx.fillStyle=state.spirit?'#ceebc278':'#fff8df55';ctx.beginPath();ctx.arc(x,y,1+rand(i+4)*2,0,Math.PI*2);ctx.fill();}
  }
  function drawIceShelf(){ctx.fillStyle='#c8dcd4';ctx.beginPath();ctx.moveTo(0,694);for(let x=0;x<W;x+=70)ctx.lineTo(x,690+Math.sin(x*.016)*19);ctx.lineTo(W,750);ctx.lineTo(0,750);ctx.fill();ctx.fillStyle='#e3ece1';for(let i=0;i<12;i++){const x=i*165-40;ctx.beginPath();ctx.moveTo(x,699);ctx.lineTo(x+40,642+rand(i)*30);ctx.lineTo(x+95,699);ctx.fill();}}
  function drawHuts(color){ctx.fillStyle='#344e4c';ctx.globalAlpha=.55;for(let i=0;i<5;i++){const x=120+i*350,y=570+rand(i)*28;ctx.fillRect(x,y,145,112);ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(x-15,y+2);ctx.lineTo(x+70,y-65);ctx.lineTo(x+160,y+2);ctx.fill();ctx.fillStyle='#344e4c';}ctx.globalAlpha=1;}
  function drawTemple(){ctx.fillStyle='#e0d9ba';ctx.globalAlpha=.8;ctx.fillRect(1070,410,430,190);for(let i=0;i<4;i++){const x=1060+i*115;ctx.fillRect(x,350,55,60);ctx.beginPath();ctx.moveTo(x-15,350);ctx.lineTo(x+26,320);ctx.lineTo(x+70,350);ctx.fill();}ctx.fillRect(1010,590,560,26);ctx.globalAlpha=1;}
  function drawVolcano(){const g=ctx.createLinearGradient(0,300,0,680);g.addColorStop(0,'#614f50');g.addColorStop(1,'#a46b55');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(880,650);ctx.lineTo(1190,270);ctx.lineTo(1490,650);ctx.fill();ctx.fillStyle='#da7954';ctx.beginPath();ctx.moveTo(1135,340);ctx.lineTo(1190,275);ctx.lineTo(1245,340);ctx.lineTo(1225,352);ctx.lineTo(1190,335);ctx.lineTo(1152,355);ctx.fill();}
  function drawCity(wall){ctx.fillStyle=wall?'#b9ad86':'#b39767';ctx.globalAlpha=.85;for(let i=0;i<8;i++){const x=i*205-15,y=510+rand(i+8)*45;ctx.fillRect(x,y,145,190);ctx.fillStyle=wall?'#d1c7a6':'#9e855d';ctx.fillRect(x-14,y-14,170,20);ctx.fillStyle=wall?'#b9ad86':'#b39767';}if(wall){ctx.fillStyle='#d5ccaa';ctx.fillRect(0,460,W,45);for(let x=0;x<W;x+=90)ctx.fillRect(x,435,48,30);}ctx.globalAlpha=1;}
  function drawTrees(){for(let i=0;i<12;i++){const x=80+i*153+rand(i+2)*70,y=430+rand(i+23)*90,ht=140+rand(i+51)*130;ctx.strokeStyle=state.spirit?'#a1cfaa':'#455c44';ctx.lineWidth=18+rand(i)*12;ctx.beginPath();ctx.moveTo(x,y+ht);ctx.bezierCurveTo(x-30,y+ht*.55,x+30,y+ht*.4,x,y);ctx.stroke();ctx.fillStyle=state.spirit?'#a4d5a078':'#71835c';ctx.beginPath();ctx.ellipse(x,y+ht*.3,40,ht*.27,0,0,Math.PI*2);ctx.fill();}}
  function drawObjects(loc){if(loc.id==='south'&&!state.spirit){for(let i=0;i<8;i++){const x=170+i*218;ctx.fillStyle='#e4eee6';ctx.beginPath();ctx.ellipse(x,870,75,31,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#c7ddd5';ctx.lineWidth=3;ctx.stroke();}}else{for(let i=0;i<11;i++){const x=80+i*165+rand(i+8)*45,y=795+rand(i+90)*230;ctx.fillStyle=state.spirit?'#9bd4a8':'#74754f';ctx.globalAlpha=.3+rand(i)*.45;ctx.beginPath();ctx.ellipse(x,y,30+rand(i+7)*25,10,rand(i)*.5,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;}}}
  function drawNPCs(loc){const npcRegion=state.spirit?locations.find(l=>l.id==='spirit'):loc;for(let i=0;i<npcRegion.npcs.length;i++){const n=npcRegion.npcs[i];const sway=Math.sin(state.time*1.1+i)*7;drawPerson(n[2]+sway,n[3],n[1]==='spirit'?'spirit':n[1]==='teacher'?'teacher':'npc',n[0]);}}
  function drawPerson(x,y,type,label){ctx.save();ctx.translate(x,y+Math.sin(state.time*3+x)*2);ctx.fillStyle='#10212638';ctx.beginPath();ctx.ellipse(0,35,23,8,0,0,Math.PI*2);ctx.fill();if(type==='spirit'){ctx.fillStyle='#c0ead0';ctx.globalAlpha=.85;ctx.beginPath();ctx.ellipse(0,-12,21,30,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#345555';ctx.beginPath();ctx.ellipse(0,-17,17,14,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e9cf87';ctx.fillRect(-10,-19,4,3);ctx.fillRect(6,-19,4,3);}else{ctx.fillStyle=type==='teacher'?'#b98a59':state.profile&&state.profile.element==='Water'?'#507e83':'#8a654f';ctx.beginPath();ctx.ellipse(0,3,14,24,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e5c4a0';ctx.beginPath();ctx.arc(0,-24,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#403a34';ctx.beginPath();ctx.arc(0,-28,11,Math.PI,0);ctx.fill();}ctx.fillStyle='#fff';ctx.font='16px sans-serif';ctx.textAlign='center';if(Math.hypot(state.x-x,state.y-y)<170)ctx.fillText('✦',0,-57);ctx.restore();}
  function drawPlayer(){ctx.save();ctx.translate(state.x,state.y+Math.sin(state.walk*9)*2);ctx.fillStyle='#14232845';ctx.beginPath();ctx.ellipse(0,32,21,8,0,0,Math.PI*2);ctx.fill();const p=state.profile;const color=state.spirit?'#d8e6ba':p?.element==='Fire'?'#bd7355':p?.element==='Earth'?'#8f9064':p?.element==='Air'?'#869f99':'#527f85';ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(0,3,14,23,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e6c6a5';ctx.beginPath();ctx.arc(0,-24,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#373c37';ctx.beginPath();ctx.arc(0,-28,11,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#f0d7a4';ctx.fillRect(state.face>0?5:-9,-26,4,2);if(state.avatar&&state.avatarControl>0){ctx.strokeStyle=`rgba(154,229,212,${.5+Math.sin(state.time*6)*.3})`;ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,-4,30+Math.sin(state.time*4)*4,0,Math.PI*2);ctx.stroke();}ctx.restore();}
  function drawEffects(){for(const p of state.particles){ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size*p.life,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}

