function drawEffects(){for(const p of state.particles){ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size*p.life,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}
function updatePanel(){const p=state.profile,el=p.avatar?'Avatar':p.element||'Non-bender';let html='';if(state.tab==='journal'){const steps=[['Meet the village elder',state.flags.metElder],['Find a moonleaf in the Misty Palms',state.flags.moonleaf],['Return with the moonleaf',state.flags.healed],['Seek a teacher in another land',state.flags.teacher]];const qtitle=['A Thread of Moonlight','A Living Remedy','A Teacher on the Road','The World Opens'][Math.min(state.quest,3)];const qdesc=['Elder Nukka has a request for a young wanderer. Find her near the village fire.','Old Kori in the Misty Palms knows where moonleaf grows. Cross the world and ask for help.','Bring the rare leaf back to Elder Nukka.','Take your first steps toward mastery. Find a teacher beyond your homeland.'][Math.min(state.quest,3)];html=`<div class="panel-kicker">YOUR JOURNAL · DAY ${String(state.day).padStart(2,'0')}</div><h2 class="panel-heading">A life in motion</h2><p class="panel-copy">The world is wide, and your story is yours to shape. Take a moment to notice what is around you.</p><div class="quest-card"><div class="panel-kicker">CURRENT THREAD</div><div class="quest-title">${qtitle}</div><p>${qdesc}</p><div class="quest-progress"><span>JOURNEY</span><b>${Math.min(state.quest,3)} / 3</b></div></div><div class="section-label">QUEST NOTES</div>${steps.map(([s,done])=>`<div class="objective ${done?'done':''}"><i>${done?'✓':''}</i><span>${s}</span></div>`).join('')}<div class="tip-card"><b>FIELD NOTE</b><br>Walk close to people and places of interest. Press <b>E</b> to talk, or tap the nearby interact button.</div>`;}else if(state.tab==='character'){html=`<div class="panel-kicker">YOUR STORY · AGE ${state.age}</div><h2 class="panel-heading">${esc(p.name)}</h2><p class="panel-copy">${esc(p.trait)} by nature, shaped by every road still ahead.</p><div class="nation-badge">${esc(p.nation.toUpperCase())}</div><div class="stat-grid"><div class="stat"><span>PATH</span><b>${el}</b></div><div class="stat"><span>LEVEL</span><b>${state.level}</b></div><div class="stat"><span>EXPERIENCE</span><b>${state.xp} XP</b></div><div class="stat"><span>RENOWN</span><b>${state.kills+state.flags.teacher?1:0}</b></div><div class="stat"><span>FAMILY</span><b style="font-size:12px">${esc(p.background)}</b></div><div class="stat"><span>PERSONALITY</span><b style="font-size:14px">${esc(p.trait)}</b></div></div><div class="section-label">A NOTE TO YOUR FUTURE SELF</div><p class="panel-copy">You were born in the ${esc(p.nation)}. ${p.avatar?'The cycle rests in your hands.':p.bender?'Your gift is a beginning, not a destiny.':'There is more than one way to change the world.'}</p>`;}else{const list=p.avatar?['Water','Earth','Fire','Air']:p.bender?[p.element]:['Non-bender'];html=`<div class="panel-kicker">PRACTICE · PATIENCE · POSSIBILITY</div><h2 class="panel-heading">Your mastery</h2><p class="panel-copy">Every technique is learned through experience and a teacher willing to share their craft.</p>${p.avatar?`<div class="tip-card"><b>THE AVATAR'S PATH</b><br>Find masters in the other nations to open each element. Build spiritual control before entering the Avatar State.</div>`:''}<div class="section-label">AVAILABLE PATHS</div>${list.map(e=>{const rank=state.mastery[e]||0;const moves=({Water:['Water whip','Ice wall','Healing flow','Plantbending'],Earth:['Rock volley','Earth wall','Seismic sense','Metal shaping'],Fire:['Flame arc','Fire wall','Lightning redirection','Dragon breath'],Air:['Air blast','Air shield','Air scooter','Flight'],NonBender:['Quick strike','Guard stance','Chi block','Counterstep']})[e];return `<div class="skill-row"><div class="skill-icon">${({Water:'≈',Earth:'◆',Fire:'♨',Air:'◌',NonBender:'✦'})[e]}</div><div><strong>${e} ${e==='NonBender'?'arts':'bending'}</strong><small>${moves[Math.min(rank,moves.length-1)]} · ${rank?'Practice rank '+rank:'Ready to begin'}</small></div><em>${rank}/4</em></div>`;}).join('')}<div class="section-label">HOW TO TRAIN</div><p class="panel-copy">Find a teacher in a region and speak with them. Use <b>SPACE</b> for your current technique. Meditate with <b>Q</b> to restore focus and deepen your connection.</p>`;}
  $('#panelContent').innerHTML=html;document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===state.tab));}
function renderAll(){if(!state.started)return;$('#regionName').textContent=(state.spirit?'SPIRIT WORLD':current().name).toUpperCase();$('#locationLabel').textContent=state.spirit?'THE VEILED GROVE':current().land;$('#weather').textContent=state.spirit?locations[7].weather:current().weather;$('#heroName').textContent=state.profile.name;$('#heroTitle').textContent=`${state.profile.avatar?'AVATAR':state.profile.bender?state.profile.element.toUpperCase()+'BENDER':'WANDERER'} · AGE ${state.age}`;$('#portrait').textContent=state.profile.avatar?'✦':({Water:'≈',Earth:'◆',Fire:'♨',Air:'◌'})[state.profile.element]||'✦';$('#healthBar').style.width=`${state.health}%`;$('#healthText').textContent=`${Math.round(state.health)} / 100`;$('#focusBar').style.width=`${state.focus/60*100}%`;$('#focusText').textContent=`${Math.round(state.focus)} / 60`;$('#clock').textContent=`DAY ${String(state.day).padStart(2,'0')} · ${state.time<11?'MORNING':state.time<17?'AFTERNOON':'EVENING'}`;updatePanel();}
function interact(){if(!state.started||overlay.classList.contains('open'))return;const nearby=nearbyNPC();if(nearby){talk(nearby);return;}if(state.region==='swamp'&&state.quest===1){state.flags.moonleaf=true;state.quest=2;gainXP(12);toast('You found a moonleaf tucked beneath the roots.');renderAll();save();return;}if(state.spirit){if(state.region!=='spirit'){state.spirit=false;}return;}showMap();}
function nearbyNPC(){const loc=state.spirit?locations[7]:current();return loc.npcs.map(n=>({n,d:Math.hypot(n[2]-state.x,n[3]-state.y)})).filter(o=>o.d<150).sort((a,b)=>a.d-b.d)[0]?.n;}
function talk(n){const [name,role]=n;let text=n[4],choices=[];if(role==='elder'&&state.quest===0&&!state.flags.metElder){text=`“${state.profile.name}, the old stories say the moonleaf can soothe a restless spirit. Would you bring one back from the Misty Palms?”`;choices=[['I’ll find it.','quest'],['Tell me about this place.','lore']];}else if(role==='elder'&&state.quest===2){text='“You found it! The leaf carries the calm of the old forest. Thank you, friend. There are teachers across the sea who can help you grow.”';choices=[['I’m ready to learn.','finish'],['Tell me about the spirits.','lore']];}else if(role==='teacher'){const e=state.profile.avatar?current().element:state.profile.element;if(!state.profile.avatar&&state.profile.element!==current().element){text=`“Your path is different from mine, ${state.profile.name}. I can share stories, but a ${state.profile.element}bender should seek a teacher of their own element.”`;choices=[['Ask about the world.','lore']];}else{text=`“Bending begins with listening. Breathe with me, then let the ${e||current().element.toLowerCase()} answer. Are you ready to practice?”`;choices=[['Train with the master.','train'],['Not just yet.','lore']];}}else if(role==='spirit'){if(name==='Hei Bai'){text='A low, mournful sound rises from the spirit. “The forest remembers a promise. Bring kindness, not fear.”';choices=[['Offer a quiet promise.','spiritQuest'],['Leave in peace.','close']];}else{text='The moon spirit circles through the luminous pool. Its presence stills the air. Your spirit feels restored.';choices=[['Sit beside the water.','heal'],['Return to the world.','close']];}}else{choices=[['Ask for a story.','lore'],['Wish them well.','close']];}showDialogue(name,text,choices);}
function showDialogue(name,text,choices){overlay.innerHTML=`<div class="modal"><div class="modal-kicker">A MOMENT SHARED</div><div class="dialogue"><div class="speaker-icon">✦</div><p><b>${esc(name)}</b>${esc(text)}</p></div><div class="choice-list">${choices.map(([label,action],i)=>`<button class="choice-button" data-choice="${action}">${String(i+1).padStart(2,'0')} &nbsp; ${esc(label)}</button>`).join('')}</div></div>`;overlay.classList.add('open');overlay.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choice(b.dataset.choice,name));}
function choice(action,name){overlay.classList.remove('open');if(action==='quest'){state.flags.metElder=true;state.quest=1;toast('New thread: find moonleaf in the Misty Palms.');}if(action==='finish'){state.flags.healed=true;state.quest=3;state.flags.teacher=true;gainXP(22);toast('Quest complete · Your journey continues.');}if(action==='train')train();if(action==='heal'){state.health=100;state.focus=60;gainXP(8);toast('The moonlit water restores you.');}if(action==='spiritQuest'){state.flags.promise=true;gainXP(10);toast('Hei Bai remembers your promise. Spirit bond +1.');}if(action==='lore')toast('A new story settles in your journal.');renderAll();save();}

