  function choice(action,name){overlay.classList.remove('open');if(action==='quest'){state.flags.metElder=true;state.quest=1;toast('New thread: find moonleaf in the Misty Palms.');}if(action==='finish'){state.flags.healed=true;state.quest=3;gainXP(22);toast('Quest complete · Your journey continues.');}if(action==='train')train();if(action==='heal'){state.health=100;state.focus=60;gainXP(8);toast('The moonlit water restores you.');}if(action==='spiritQuest'){state.flags.promise=true;gainXP(10);toast('Hei Bai remembers your promise. Spirit bond +1.');}if(action==='lore')toast('A new story settles in your journal.');renderAll();save();}
  function showMap(){const cards=locations.filter(l=>l.id!=='spirit');overlay.innerHTML=`<div class="modal"><div class="modal-kicker">THE WORLD IS WIDE · TRAVEL BY MEMORY</div><h2>Choose your next horizon.</h2><p>Journeys between distant lands are simplified for this story. Choose a place you have heard of, or follow the paths marked by the people you meet.</p><div class="choice-list">${cards.map(l=>`<button class="choice-button" data-region="${l.id}">${l.element==='Water'?'≈':l.element==='Earth'?'◆':l.element==='Fire'?'♨':'◌'} &nbsp; ${esc(l.name)} <span style="float:right;color:#9a9f91;font-size:9px">${esc(l.land)}</span></button>`).join('')}</div><div class="modal-actions"><button class="secondary-button" id="closeMap">STAY HERE</button></div></div>`;overlay.classList.add('open');overlay.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>travel(b.dataset.region));$('#closeMap').onclick=()=>overlay.classList.remove('open');}
  function travel(id){state.region=id;state.spirit=false;state.x=420;state.y=630;if(!state.visited.includes(id))state.visited.push(id);state.time+=2;if(state.time>=24){state.day++;state.time%=24;if(state.day%365===0)state.age++;}overlay.classList.remove('open');renderAll();toast(`Arrived at ${current().name}.`);save();}
  function train(){const p=state.profile;if(!p.avatar&&!p.bender){toast('The master smiles. Practice your own non-bender discipline.');p.bender=false;state.mastery.NonBender=(state.mastery.NonBender||0)+1;gainXP(15);return;}const e=p.avatar?current().element:p.element;if(p.avatar&&e==='Spirit'){state.avatarControl=Math.min(3,state.avatarControl+1);gainXP(20);toast('Your connection deepens. Avatar State control increased.');}else if(p.avatar&&!state.mastery[e]&&e!==p.element){state.mastery[e]=0;toast(`${e} path unlocked. Train to learn your first technique.`);}else{state.mastery[e]=(state.mastery[e]||0)+1;state.focus=Math.min(60,state.focus+18);gainXP(18);toast(`${e} mastery grows · rank ${state.mastery[e]}.`);}if(p.avatar&&state.mastery.Water>=1&&state.mastery.Earth>=1&&state.mastery.Fire>=1&&state.mastery.Air>=1){state.avatarControl=Math.max(1,state.avatarControl);toast('All four elements answer your call.');}renderAll();save();}
  function gainXP(amount){state.xp+=amount;const threshold=state.level*45;if(state.xp>=threshold){state.xp-=threshold;state.level++;state.health=100;state.focus=60;state.age=Math.max(16,state.age+1);toast(`Level ${state.level} · You grow stronger and a year older.`);}}
  function meditate(){if(!state.started)return;if(state.profile.avatar&&state.avatarControl>0){state.avatarControl=Math.min(3,state.avatarControl);state.spirit=!state.spirit;state.focus=state.spirit?Math.max(0,state.focus-8):state.focus;toast(state.spirit?'The veil thins. You enter the Spirit World.':'Your spirit returns to the physical world.');renderAll();save();return;}state.meditating=true;state.focus=Math.min(60,state.focus+22);state.health=Math.min(100,state.health+6);state.time+=.5;addParticles(state.x,state.y-20,'#b8e3d3',16);gainXP(2);toast('A quiet breath. Focus restored.');renderAll();save();}
  function addParticles(x,y,color,count){for(let i=0;i<count;i++)state.particles.push({x,y,vx:(Math.random()-.5)*140,vy:(Math.random()-.7)*140,life:.5+Math.random()*.8,size:2+Math.random()*5,color});}
  function attack(){if(!state.started||overlay.classList.contains('open'))return;if(state.focus<5){toast('You need a moment to catch your breath.');return;}state.focus=Math.max(0,state.focus-5);const p=state.profile;const e=state.spirit?'Spirit':p.avatar?current().element:p.bender?p.element:'NonBender';const color=({Water:'#79d5e0',Earth:'#d4bc7c',Fire:'#ff9864',Air:'#d6e8db',Spirit:'#c8f1ba',NonBender:'#ffe1a0'})[e];const tx=state.x+state.face*85;addParticles(tx,state.y-14,color,13);state.particles.forEach(q=>{if(q.x===tx)q.vx+=state.face*100;});const loc=state.spirit?locations[7]:current();const target=loc.npcs.find(n=>n[1]==='spirit'&&Math.hypot(n[2]-tx,n[3]-state.y)<135);if(target){if(state.enemyName!==target[0]){state.enemyName=target[0];state.enemyHP=100;}state.enemyHP-=22+(state.mastery[e]||0)*6;if(state.enemyHP<=0){state.kills++;state.flags.spiritCalmed=true;gainXP(25);toast(`${target[0]} is calmed. The spirit leaves in peace.`);state.enemyName=null;state.enemyHP=0;}else toast(`${e} technique · spirit unsettled (${state.enemyHP}%).`);}else if(nearbyNPC()){toast(`A practiced ${e} technique. The nearby folk step back.`);}else toast(`${e} technique released.`);renderAll();save();}
  const keys=new Set();
  function keydown(e){if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.repeat)return;if(e.key==='Escape'){overlay.classList.remove('open');return;}if(overlay.classList.contains('open'))return;const k=e.key.toLowerCase();if(k==='e'||k==='enter')interact();if(k==='q')meditate();if(k==='m')showMap();if(k===' '||k==='f')attack();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k))keys.add(k);}
  function keyup(e){keys.delete(e.key.toLowerCase());}
  window.addEventListener('keydown',keydown);window.addEventListener('keyup',keyup);window.addEventListener('blur',()=>keys.clear());
  function move(dt){if(!state.started||overlay.classList.contains('open'))return;let dx=0,dy=0;if(keys.has('w')||keys.has('arrowup'))dy--;if(keys.has('s')||keys.has('arrowdown'))dy++;if(keys.has('a')||keys.has('arrowleft'))dx--;if(keys.has('d')||keys.has('arrowright'))dx++;const mag=Math.hypot(dx,dy)||1;dx/=mag;dy/=mag;const boost=state.profile.avatar&&state.avatarControl>0&&state.avatarActive?1.5:1;state.x=Math.max(35,Math.min(W-35,state.x+dx*245*boost*dt));state.y=Math.max(450,Math.min(H-45,state.y+dy*245*boost*dt));if(dx)state.face=Math.sign(dx);if(dx||dy)state.walk+=dt;}
  function loop(now){const dt=Math.min(.04,(now-lastFrame)/1000);lastFrame=now;state.time+=dt*.04;move(dt);state.particles=state.particles.filter(p=>p.life>0);for(const p of state.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt*1.1;p.vx*=.98;p.vy*=.98;}if(state.toastTimer>0){state.toastTimer-=dt;if(state.toastTimer<=0)$('#toast').classList.remove('show');}draw();requestAnimationFrame(loop);}
  document.querySelectorAll('.tab').forEach(t=>t.addEventListener('click',()=>{state.tab=t.dataset.tab;updatePanel();}));document.querySelectorAll('.mobile-tabs button').forEach(t=>t.addEventListener('click',()=>{state.tab=t.dataset.panel;updatePanel();if(t.dataset.panel==='map')showMap();}));$('#mapButton').onclick=showMap;$('#meditateButton').onclick=meditate;$('#soundButton').onclick=()=>{state.sound=!state.sound;$('#soundButton').innerHTML=state.sound?'♫ <span>On</span>':'♫ <span>Sound</span>';toast('Ambient sound '+(state.sound?'enabled':'muted')+'.');};$('#touchInteract').onclick=interact;$('#touchAction').onclick=attack;
  document.querySelectorAll('.mobile-pad button').forEach(b=>{const dir=b.dataset.dir;const map={up:'w',down:'s',left:'a',right:'d'};const k=map[dir];b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(k);b.setPointerCapture(e.pointerId);});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys.delete(k)));});
  resize();requestAnimationFrame(loop);if(load()){renderAll();showWelcome();}else showWelcome();
})();

